/bin/bash -lc "python - <<'PY'
import glob,re
for pat in ['CHIP','Glu','HERTZ','HOLIDAY','Pelican','REWALK','Integrity','Steel','GIGG','SEPARATE','IMAGE','Leju','SCOUT']:
 for f in glob.glob(pat+'*.txt'):
  print('\\n'+pat)
  for p in re.split(r'--- page (\\d+) ---',open(f).read())[1:][::2]: pass
  a=re.split(r'--- page (\\d+) ---',open(f).read().replace('\\xa0',' '))
  for i in range(1,len(a),2):
   for l in a[i+1].splitlines():
    if re.search(r'(?i)(term and termination|term of this agreement (?:shall|will|is)|this agreement (?:shall|will|may) (?:terminate|continue|commence|remain|be effective)|terminate this agreement|automat.*renew|perpetu|continu.*indefinite|"'^'"\\s*\\d+\\.?\\d*\\s+term\\b|unless and until)',l): print(a[i],l.strip()[:210])
PY"

