import glob,re
for f in sorted(glob.glob('*.txt')):
 print('\\n'+f.split('_')[0])
 a=re.split(r'--- page (\\d+) ---',open(f).read().replace('\\xa0',' '))
 for i in range(1,len(a),2):
  for l in a[i+1].splitlines():
   if re.search(r'(?i)(term and termination|term of (?:this agreement|contract) (?:shall|will|is)|this agreement (?:shall|will|may) (?:terminate|continue|commence|remain|be effective)|automat.*renew|perpetu|continu.*indefinite|"'^'"\\s*\\d+\\.?\\d*\\s+term\\b|unless and until|\\b(?:term|termination|duration)\\s*[:.]|until .*terminat)',l): print(a[i],l.strip()[:190])
